from taf.ul.ettf.sim.core.command import Command
from taf.ul.ettf.throughput.common_options import TypeOptions
from taf.ul.ettf.throughput.common_throughput import CommonThroughput
from taf.ul.ettf.throughput.parsers import ThroughputParser
from taf.ul.ettf.throughput.throughtput_command import ThroughputCommand
from taf.ul.ettf.throughput.validator import AssertThatThroughput, BasicValidator
from taf.ul.ettf.sim.core.validators import Validators
from taf.ul.ettf.throughput.assertion_conditions import EqualsTo, Reaches


class UeThroughputCommand(ThroughputCommand):
    def __init__(self, ue_id, validators=Validators()):
        super(UeThroughputCommand, self).__init__('ue_stats_nr id={}'.format(ue_id), validators, ThroughputParser())
        self.add_param('size_unit', 'bytes')
        Command.command_elements.add_modulator('selection_type', 'Average')


class UeThroughputOptions(CommonThroughput):
    pass


class UeThroughputAssertions(CommonThroughput):
    def get_ue_throughput(self, ue_id):
        return self.init_simple_command(UeThroughputCommand(ue_id, Validators(BasicValidator())))

    def assert_that_ue_throughput_equals(self, ue_id, expected_throughput,
                                         selection_type=None, parameter=None, margin=.0):
        validator = AssertThatThroughput(EqualsTo(expected_throughput), selection_type, parameter, margin)
        self.init_command(UeThroughputCommand(ue_id, Validators(validator)))

    def assert_that_expected_ue_throughput_is_reached(self, ue_id, expected_throughput,
                                                      selection_type=None, parameter=None, margin=.0):
        validator = AssertThatThroughput(Reaches(expected_throughput), selection_type, parameter, margin)
        self.init_command(UeThroughputCommand(ue_id, Validators(validator)))

    def assert_that_ue_throughput(self, ue_id):
        self.start()
        self.init_command(UeThroughputCommand(ue_id))


class UeThroughput(UeThroughputOptions, UeThroughputAssertions, TypeOptions):
    pass


ue = UeThroughput
